{
  "name": "opencode-ds-websearch",
  "version": "1.0.0",
  "description": "DeepSeek web search for OpenCode: structured filters, content control, retries, quality signals and automatic fallback.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "deepseek",
    "websearch",
    "search"
  ],
  "license": "MIT",
  "scripts": {
    "test": "bun test"
  }
}

/**
 * OpenCode plugin: DeepSeek web search with automatic fallback.
 *
 * Registers a tool named `websearch`, which takes precedence over the built-in
 * tool of the same name (OpenCode docs: "If a plugin tool uses the same name as
 * a built-in tool, the plugin tool takes precedence").
 *
 * Behaviour:
 *   1. Try DeepSeek POST /v1/tools/search (better Chinese recall, authority + rerank scores)
 *      - structured filters (site / -site / lang / after / before / -terms) are folded into `query`
 *      - `need_content` returns page body, capped by a per-hit and a total char budget
 *      - transient errors (408 / 429 / 5xx) are retried with backoff, honouring Retry-After
 *   2. On failure or an empty result set, fall back to OpenCode's own search channel
 *      (TinyFish keyless MCP) — the fallback reason is always stated in the output
 *   3. If both fail, surface both errors instead of returning a silent empty result
 *
 * Credentials are resolved per call: explicit override -> DEEPSEEK_API_KEY ->
 * the `deepseek` provider key in this machine's opencode config. No key is ever
 * written into this file or into the tool output.
 */

import { existsSync, readFileSync } from "node:fs"
import { homedir } from "node:os"
import { join } from "node:path"

// ---------------------------------------------------------------------------
// Endpoints & limits
// ---------------------------------------------------------------------------

export const DS_SEARCH_URL = "https://api.deepseek.com/v1/tools/search"
export const TINYFISH_URL = "https://agent.tinyfish.ai/mcp"

const DS_TIMEOUT_MS = 15_000
const DS_TIMEOUT_CONTENT_MS = 25_000
const TF_TIMEOUT_MS = 20_000

export const COUNT_DEFAULT = 8
export const COUNT_MAX = 50
const QUERY_MAX = 128
const ORI_QUESTION_MAX = 128

const PER_HIT_CONTENT_CHARS = 3_000
const TOTAL_CONTENT_CHARS = 12_000
const SUMMARY_CHARS = 500
const SNIPPET_CHARS = 240
const TITLE_CHARS = 160
/** Below this rerank score the hit is annotated as low relevance; never filtered. */
const LOW_SCORE = 0.8

const RETRY_ATTEMPTS = 3
const RETRY_BASE_MS = 600
const RETRY_MAX_WAIT_MS = 3_000

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type SearchHit = {
  title: string
  url: string
  snippet?: string
  summary?: string
  content?: string
  site?: string
  siteIcon?: string
  date?: string
  authority?: number
  score?: number
}

export type SearchOutcome = {
  source: "deepseek" | "tinyfish" | "none"
  hits: SearchHit[]
  notice?: string
  errors: string[]
  /** Final query actually sent upstream (after structured filters were folded in). */
  query: string
  degraded: boolean
  emptyDeepseek: boolean
  needContent: boolean
}

export type SearchRequest = {
  query: string
  /** 1..50, default 8. */
  count?: number
  /** Ask DeepSeek for page bodies in `content`. */
  needContent?: boolean
  /** Original user question, improves intent understanding (<=128 chars). */
  oriQuestion?: string
  site?: string | string[]
  excludeSites?: string | string[]
  lang?: string | string[]
  after?: string
  before?: string
  excludeTerms?: string | string[]
  /** IP used for localized results. Not inferred automatically; prefer the env var. */
  localization?: string
}

export type RetryPolicy = {
  /** Total attempts, including the first one. Default 3. */
  attempts?: number
  /** Base backoff in ms, doubled per attempt. Default 600. */
  baseDelayMs?: number
}

export type SearchOptions = {
  /** Endpoint overrides, used by the test harness. */
  dsUrl?: string
  tfUrl?: string
  /** Key overrides, used by the test harness. */
  apiKey?: string | null
  tinyfishKey?: string | null
  /** Outer cancellation (tool abort). Never retried once aborted. */
  signal?: AbortSignal
  /** Per-attempt timeout override, used by the test harness. */
  timeoutMs?: number
  retry?: RetryPolicy
  /** fetch override, used by the test harness. */
  fetchImpl?: typeof fetch
}

export type BuiltQuery = {
  query: string
  addedFilters: string[]
  oriQuestion?: string
  localization?: string
}

export type QueryBuildResult =
  | { ok: true; built: BuiltQuery }
  | { ok: false; error: string }

class QueryError extends Error {}

class HttpError extends Error {
  status: number
  retryAfterMs?: number

  constructor(status: number, body: string, retryAfter: string | null) {
    super(`HTTP ${status} ${body.slice(0, 200)}`)
    this.status = status
    const parsed = parseRetryAfter(retryAfter)
    if (parsed !== undefined) this.retryAfterMs = parsed
  }
}

// ---------------------------------------------------------------------------
// Credential resolution
// ---------------------------------------------------------------------------

/**
 * Order: explicit override -> env -> opencode config file.
 * Returning null is a valid state ("DeepSeek unavailable"), not an exception.
 */
export function resolveApiKey(override?: string | null): string | null {
  if (override !== undefined) return override
  if (process.env.DEEPSEEK_API_KEY) return process.env.DEEPSEEK_API_KEY

  const dir = join(homedir(), ".config", "opencode")
  for (const name of ["opencode.json", "opencode.jsonc"]) {
    const file = join(dir, name)
    if (!existsSync(file)) continue
    try {
      const parsed = JSON.parse(stripJsonc(readFileSync(file, "utf8")))
      const key = parsed?.providers?.deepseek?.settings?.apiKey
      if (typeof key === "string" && key.trim()) return key.trim()
    } catch {
      // A malformed config must not break search; try the next candidate.
    }
  }
  return null
}

/** Minimal JSONC support so opencode.jsonc works as well as opencode.json. */
function stripJsonc(raw: string): string {
  let out = ""
  let inString = false
  let inLine = false
  let inBlock = false
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i]
    const n = raw[i + 1]
    if (inLine) {
      if (c === "\n") {
        inLine = false
        out += c
      }
      continue
    }
    if (inBlock) {
      if (c === "*" && n === "/") {
        inBlock = false
        i++
      }
      continue
    }
    if (inString) {
      out += c
      if (c === "\\") {
        out += n ?? ""
        i++
      } else if (c === '"') {
        inString = false
      }
      continue
    }
    if (c === '"') {
      inString = true
      out += c
      continue
    }
    if (c === "/" && n === "/") {
      inLine = true
      i++
      continue
    }
    if (c === "/" && n === "*") {
      inBlock = true
      i++
      continue
    }
    out += c
  }
  return out.replace(/,(\s*[}\]])/g, "$1")
}

export function resolveTinyfishKey(override?: string | null): string | null {
  if (override !== undefined) return override
  return process.env.TINYFISH_API_KEY || null
}

// ---------------------------------------------------------------------------
// Query building (structured filters -> DeepSeek search syntax)
// ---------------------------------------------------------------------------

function chars(s: string): number {
  return Array.from(s).length
}

function takeChars(text: string, max: number): { text: string; truncated: boolean; total: number } {
  const list = Array.from(text)
  return { text: list.slice(0, max).join(""), truncated: list.length > max, total: list.length }
}

function toHostList(value?: string | string[]): string[] {
  if (!value) return []
  const raw = Array.isArray(value) ? value : [value]
  return raw
    .flatMap((v) => String(v).split(/[,，\s]+/))
    .map((s) => normalizeHost(s))
    .filter(Boolean)
}

function normalizeHost(raw: string): string {
  const s = raw
    .trim()
    .replace(/^[a-z][a-z0-9+.-]*:\/\//i, "")
    .split(/[/?#]/)[0]
    .replace(/\.+$/, "")
    .toLowerCase()
  return s
}

function isHostLike(host: string): boolean {
  if (!host) return false
  if (host === "localhost") return true
  const ipv4 = /^\d{1,3}(\.\d{1,3}){3}$/
  if (ipv4.test(host)) return true
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/i.test(host)
}

function toLangList(value?: string | string[]): string[] {
  if (!value) return []
  const raw = Array.isArray(value) ? value : [value]
  const out: string[] = []
  for (const item of raw.flatMap((v) => String(v).split(/[,，\s]+/))) {
    const lang = item.trim()
    if (!lang) continue
    if (!/^[a-z]{2}(-[a-zA-Z]{2})?$/.test(lang)) {
      throw new QueryError(`语言代码不合法（${lang}），应形如 zh、en 或 zh-CN`)
    }
    out.push(lang)
  }
  return out
}

function toTermList(value?: string | string[]): string[] {
  if (!value) return []
  const raw = Array.isArray(value) ? value : String(value).split(/[,，]/)
  return raw.map((s) => s.trim()).filter(Boolean)
}

function normalizeDate(value: string, field: "after" | "before"): string {
  const v = value.trim()
  const m = /^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?$/.exec(v)
  if (!m) {
    throw new QueryError(`${field} 日期格式不合法（${value}），应形如 2025、2025-01 或 2025-01-31`)
  }
  const year = Number(m[1])
  const month = m[2] === undefined ? undefined : Number(m[2])
  const day = m[3] === undefined ? undefined : Number(m[3])
  if (month !== undefined && (month < 1 || month > 12)) {
    throw new QueryError(`${field} 月份不存在（${value}）`)
  }
  if (day !== undefined) {
    const asUtc = new Date(Date.UTC(year, (month ?? 1) - 1, day))
    if (
      asUtc.getUTCFullYear() !== year ||
      asUtc.getUTCMonth() !== (month ?? 1) - 1 ||
      asUtc.getUTCDate() !== day
    ) {
      throw new QueryError(`${field} 日期不存在（${value}）`)
    }
  }
  return v
}

function normalizeLocalization(value: string): string {
  const v = value.trim()
  const ipv4 = /^\d{1,3}(\.\d{1,3}){3}$/
  const ipv6 = /^[0-9a-fA-F:]+$/
  if (!ipv4.test(v) && !ipv6.test(v)) {
    throw new QueryError(`localization 必须是 IP 地址（收到 ${value}）`)
  }
  return v
}

/**
 * Both `buildQuery` and `search` need this: `search` turns the error into a
 * model-readable notice, tests call `buildQuery` directly.
 */
export function buildQuery(req: SearchRequest): QueryBuildResult {
  try {
    return { ok: true, built: buildQueryOrThrow(req) }
  } catch (err) {
    return { ok: false, error: describeError(err) }
  }
}

function buildQueryOrThrow(req: SearchRequest): BuiltQuery {
  const base = String(req.query ?? "").trim()
  if (!base) throw new QueryError("查询为空")
  const baseLength = chars(base)
  if (baseLength > QUERY_MAX) {
    throw new QueryError(`查询过长（${baseLength} > ${QUERY_MAX} 字符），请缩短或拆分后再搜`)
  }

  const added: string[] = []
  let query = base

  const push = (clause: string) => {
    if (!clause) return
    query = `${query} ${clause}`
    added.push(clause)
  }
  const hasOperator = (name: string, negated = false) =>
    new RegExp(`(^|\\s)${negated ? "-" : "-?"}${name}:`, "i").test(query)

  const sites = toHostList(req.site)
  for (const host of sites) {
    if (!isHostLike(host)) throw new QueryError(`站点格式不合法（${host}）`)
  }
  if (sites.length && !hasOperator("site")) push(sites.map((h) => `site:${h}`).join(" OR "))

  const excludedSites = toHostList(req.excludeSites)
  for (const host of excludedSites) {
    if (!isHostLike(host)) throw new QueryError(`排除站点格式不合法（${host}）`)
  }
  if (excludedSites.length && !hasOperator("site", true)) {
    push(excludedSites.map((h) => `-site:${h}`).join(" "))
  }

  const langs = toLangList(req.lang)
  if (langs.length && !hasOperator("lang")) push(`lang:${langs.join(",")}`)

  if (req.after) {
    const v = normalizeDate(req.after, "after")
    if (!hasOperator("after")) push(`after:${v}`)
  }
  if (req.before) {
    const v = normalizeDate(req.before, "before")
    if (!hasOperator("before")) push(`before:${v}`)
  }

  const termClauses = toTermList(req.excludeTerms).map((t) => (/\s/.test(t) ? `-"${t}"` : `-${t}`))
  const missingTerms = termClauses.filter((clause) => !query.includes(clause))
  if (missingTerms.length) push(missingTerms.join(" "))

  const queryLength = chars(query)
  if (queryLength > QUERY_MAX) {
    throw new QueryError(
      `拼接筛选条件后查询达到 ${queryLength} 字符，超过 ${QUERY_MAX} 上限；请缩短 query 或减少筛选条件`,
    )
  }

  let oriQuestion: string | undefined
  if (req.oriQuestion && req.oriQuestion.trim()) {
    const q = req.oriQuestion.trim()
    oriQuestion = chars(q) > ORI_QUESTION_MAX ? takeChars(q, ORI_QUESTION_MAX).text : q
  }

  let localization: string | undefined
  if (req.localization && String(req.localization).trim()) {
    localization = normalizeLocalization(String(req.localization))
  }

  return { query, addedFilters: added, oriQuestion, localization }
}

// ---------------------------------------------------------------------------
// Transport helpers
// ---------------------------------------------------------------------------

function abortError(): Error {
  const err = new Error("请求已取消")
  err.name = "AbortError"
  return err
}

function combineSignals(signals: Array<AbortSignal | undefined>): AbortSignal | undefined {
  const list = signals.filter((s): s is AbortSignal => !!s)
  if (list.length === 0) return undefined
  if (list.length === 1) return list[0]
  const anyFn = (AbortSignal as unknown as { any?: (s: AbortSignal[]) => AbortSignal }).any
  if (typeof anyFn === "function") return anyFn(list)

  const controller = new AbortController()
  const forward = (signal: AbortSignal) => {
    if (!controller.signal.aborted) controller.abort((signal as AbortSignal & { reason?: unknown }).reason)
  }
  for (const signal of list) {
    if (signal.aborted) {
      forward(signal)
      break
    }
    signal.addEventListener("abort", () => forward(signal), { once: true })
  }
  return controller.signal
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(abortError())
      return
    }
    const timer = setTimeout(() => {
      cleanup()
      resolve()
    }, ms)
    const onAbort = () => {
      cleanup()
      reject(abortError())
    }
    const cleanup = () => {
      clearTimeout(timer)
      signal?.removeEventListener("abort", onAbort)
    }
    signal?.addEventListener("abort", onAbort, { once: true })
  })
}

function parseRetryAfter(raw: string | null | undefined): number | undefined {
  if (!raw) return undefined
  const trimmed = raw.trim()
  if (!trimmed) return undefined
  const seconds = Number(trimmed)
  if (Number.isFinite(seconds) && seconds >= 0) return Math.round(seconds * 1000)
  const when = Date.parse(trimmed)
  if (!Number.isNaN(when)) return Math.max(0, when - Date.now())
  return undefined
}

async function safeText(res: Response): Promise<string> {
  try {
    return await res.text()
  } catch {
    return ""
  }
}

function isRetryable(err: unknown): boolean {
  if (err instanceof HttpError) {
    return err.status === 408 || err.status === 429 || err.status >= 500
  }
  if (err instanceof Error) {
    if (err.name === "TimeoutError") return true
    if (err.name === "AbortError") return true
    // Undici/Node network failure ("fetch failed", ECONNRESET, ...) has no status.
    return true
  }
  return false
}

// ---------------------------------------------------------------------------
// Providers
// ---------------------------------------------------------------------------

function clampCount(count: number | undefined): number {
  if (typeof count !== "number" || !Number.isFinite(count)) return COUNT_DEFAULT
  return Math.min(COUNT_MAX, Math.max(1, Math.trunc(count)))
}

function normalizeHits(raw: any[], needContent: boolean): SearchHit[] {
  return raw.map((r) => ({
    title: String(r?.title ?? ""),
    url: String(r?.url ?? ""),
    snippet: r?.snippet || undefined,
    summary: r?.summary || undefined,
    content: needContent && r?.content ? String(r.content) : undefined,
    site: r?.site_name || undefined,
    siteIcon: r?.site_icon || undefined,
    date: r?.date || undefined,
    authority: typeof r?.authority === "number" ? r.authority : undefined,
    score: typeof r?.rerank_score === "number" ? r.rerank_score : undefined,
  }))
}

function normalizeUrlKey(url: string): string {
  return url
    .trim()
    .replace(/#.*$/, "")
    .replace(/\/+$/, "")
    .replace(/^([a-z]+:\/\/)([^/]+)/i, (_m, scheme: string, host: string) => `${scheme.toLowerCase()}${host.toLowerCase()}`)
}

function dedupeHits(hits: SearchHit[]): SearchHit[] {
  const seen = new Set<string>()
  const out: SearchHit[] = []
  for (const hit of hits) {
    const key = normalizeUrlKey(hit.url) || hit.title
    if (key && seen.has(key)) continue
    if (key) seen.add(key)
    out.push(hit)
  }
  return out
}

async function dsSearch(
  built: BuiltQuery,
  count: number,
  needContent: boolean,
  opts: SearchOptions,
): Promise<SearchHit[]> {
  const key = resolveApiKey(opts.apiKey)
  if (!key) {
    throw new Error("未找到 DeepSeek API key（请设置 DEEPSEEK_API_KEY，或在本机 opencode 配置中填写 deepseek provider key）")
  }

  const payload: Record<string, unknown> = {
    query: built.query,
    count,
    need_content: needContent,
  }
  if (built.oriQuestion) payload.ori_question = built.oriQuestion
  const localization = built.localization ?? process.env.DEEPSEEK_SEARCH_LOCALIZATION
  if (localization) payload.localization = normalizeLocalization(localization)

  const doFetch = opts.fetchImpl ?? fetch
  const attempts = Math.max(1, Math.trunc(opts.retry?.attempts ?? RETRY_ATTEMPTS))
  const baseDelay = Math.max(0, opts.retry?.baseDelayMs ?? RETRY_BASE_MS)
  const timeoutMs = opts.timeoutMs ?? (needContent ? DS_TIMEOUT_CONTENT_MS : DS_TIMEOUT_MS)

  let lastError: unknown

  for (let attempt = 0; attempt < attempts; attempt++) {
    const signal = combineSignals([opts.signal, AbortSignal.timeout(timeoutMs)])
    try {
      const res = await doFetch(opts.dsUrl ?? DS_SEARCH_URL, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${key}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
        signal,
      })

      if (!res.ok) {
        throw new HttpError(res.status, await safeText(res), res.headers?.get?.("retry-after") ?? null)
      }

      const json = (await res.json()) as { results?: any[] }
      return normalizeHits(Array.isArray(json?.results) ? json.results : [], needContent)
    } catch (err) {
      lastError = err
      if (opts.signal?.aborted) throw abortError()
      const canRetry = attempt < attempts - 1 && isRetryable(err)
      if (!canRetry) throw err
      const hinted = err instanceof HttpError ? err.retryAfterMs : undefined
      const wait = Math.min(hinted ?? baseDelay * 2 ** attempt, RETRY_MAX_WAIT_MS)
      await sleep(wait, opts.signal)
    }
  }

  throw lastError
}

async function tinyfishSearch(query: string, count: number, opts: SearchOptions): Promise<SearchHit[]> {
  const key = resolveTinyfishKey(opts.tinyfishKey)
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "MCP-Protocol-Version": "2025-11-25",
  }
  if (key) headers["X-API-Key"] = key
  else headers["X-TinyFish-Access-Mode"] = "keyless"

  const doFetch = opts.fetchImpl ?? fetch
  const res = await doFetch(opts.tfUrl ?? TINYFISH_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "tools/call",
      params: { name: "search", arguments: { query, purpose: "agent web search" } },
    }),
    signal: combineSignals([opts.signal, AbortSignal.timeout(TF_TIMEOUT_MS)]),
  })

  if (!res.ok) throw new HttpError(res.status, await safeText(res), res.headers?.get?.("retry-after") ?? null)

  const json = (await res.json()) as any
  if (json.error) throw new Error(`MCP error: ${JSON.stringify(json.error).slice(0, 200)}`)

  const text = json?.result?.content?.find?.((c: any) => c?.type === "text")?.text
  if (!text) throw new Error("MCP 返回内容为空")

  let payload: any
  try {
    payload = JSON.parse(text)
  } catch {
    throw new Error("MCP 返回内容无法解析")
  }

  return (Array.isArray(payload?.results) ? payload.results : []).slice(0, count).map((r: any) => ({
    title: String(r?.title ?? ""),
    url: String(r?.url ?? ""),
    snippet: r?.snippet || undefined,
    site: r?.site_name || undefined,
    date: r?.date || undefined,
  }))
}

// ---------------------------------------------------------------------------
// Orchestration
// ---------------------------------------------------------------------------

const HTTP_HINTS: Record<number, string> = {
  400: "请求不合法（查询或参数格式问题）",
  401: "401 鉴权失败（API key 无效）",
  402: "402 余额不足",
  403: "403 被安全策略拒绝",
  404: "404 无法获取可解析的网页内容",
  408: "408 请求超时",
  413: "413 请求体过大",
  429: "429 触发限流",
  500: "500 服务端错误",
  504: "504 下游超时",
}

export function describeError(err: unknown): string {
  if (err instanceof QueryError) return err.message
  if (err instanceof HttpError) {
    const hint = HTTP_HINTS[err.status]
    if (hint) return hint
    if (err.status >= 500) return `${err.status} 服务端错误`
    return `HTTP ${err.status}`
  }
  if (err instanceof Error) {
    if (err.name === "TimeoutError") return "请求超时"
    if (err.name === "AbortError") return "请求被取消"
    if (err.message === "fetch failed" || err.name === "TypeError") return "网络错误（连接失败）"
    return err.message
  }
  return String(err)
}

export async function search(req: SearchRequest, opts: SearchOptions = {}): Promise<SearchOutcome> {
  const count = clampCount(req.count)
  const needContent = req.needContent === true
  const errors: string[] = []
  const rawQuery = String(req?.query ?? "")

  const builtResult = buildQuery({ ...req, query: rawQuery })
  if (!builtResult.ok) {
    return {
      source: "none",
      hits: [],
      errors: [builtResult.error],
      query: rawQuery,
      degraded: false,
      emptyDeepseek: false,
      needContent,
      notice: `❌ 查询无效：${builtResult.error}`,
    }
  }
  const built = builtResult.built

  let dsFailed = false
  try {
    const hits = dedupeHits(await dsSearch(built, count, needContent, opts))
    if (hits.length > 0) {
      return {
        source: "deepseek",
        hits,
        errors,
        query: built.query,
        degraded: false,
        emptyDeepseek: false,
        needContent,
      }
    }
    errors.push("DeepSeek 返回 0 条结果")
  } catch (err) {
    dsFailed = true
    errors.push(`DeepSeek: ${describeError(err)}`)
  }

  if (opts.signal?.aborted) {
    return {
      source: "none",
      hits: [],
      errors,
      query: built.query,
      degraded: false,
      emptyDeepseek: false,
      needContent,
      notice: "搜索已取消。",
    }
  }

  let tfFailed = false
  let tfReason = ""
  try {
    const hits = dedupeHits(await tinyfishSearch(built.query, count, opts))
    if (hits.length > 0) {
      const notice = dsFailed
        ? `⚠️ DeepSeek 搜索不可用（${errors[0]}），已自动降级到备用搜索。以下结果来自 TinyFish。`
        : "ℹ️ DeepSeek 正常返回但无匹配结果，以下为备用搜索 TinyFish 的补查结果。"
      return {
        source: "tinyfish",
        hits,
        errors,
        query: built.query,
        // Supplementing a healthy-but-empty primary channel is coverage, not degradation.
        degraded: dsFailed,
        emptyDeepseek: !dsFailed,
        needContent,
        notice,
      }
    }
    if (!dsFailed) errors.push("TinyFish 补查也返回 0 条结果")
  } catch (err) {
    tfFailed = true
    tfReason = describeError(err)
    errors.push(`TinyFish: ${tfReason}`)
  }

  if (dsFailed) {
    return {
      source: "none",
      hits: [],
      errors,
      query: built.query,
      degraded: true,
      emptyDeepseek: false,
      needContent,
      notice: `❌ 两条搜索通道都失败：${errors.join("；")}`,
    }
  }

  const notice = tfFailed
    ? `没有匹配结果（DeepSeek 正常返回 0 条；备用通道失败：${tfReason}）。建议放宽关键词或去掉筛选条件。`
    : "没有匹配结果（DeepSeek 与备用通道均正常返回 0 条）。建议放宽关键词或去掉筛选条件。"
  return {
    source: "none",
    hits: [],
    errors,
    query: built.query,
    degraded: tfFailed,
    emptyDeepseek: true,
    needContent,
    notice,
  }
}

// ---------------------------------------------------------------------------
// Formatting
// ---------------------------------------------------------------------------

function clip(text: string | undefined, max: number): string {
  if (!text) return ""
  const t = text.replace(/\s+/g, " ").trim()
  return t.length > max ? `${t.slice(0, max)}…` : t
}

function formatDate(raw: string): string {
  // Keep the date the API reported; converting across timezones can shift the
  // day (e.g. a UTC+08 publication dated 04-24 turning into 04-23).
  const prefix = /^(\d{4})-(\d{2})-(\d{2})/.exec(raw)
  if (prefix) return `${prefix[1]}-${prefix[2]}-${prefix[3]}`
  const parsed = Date.parse(raw)
  if (!Number.isNaN(parsed)) return new Date(parsed).toISOString().slice(0, 10)
  return raw.slice(0, 10)
}

export function format(outcome: SearchOutcome): string {
  const lines: string[] = []
  if (outcome.notice) lines.push(outcome.notice, "")

  if (outcome.hits.length === 0) {
    lines.push("没有找到结果。")
    return lines.join("\n").trimEnd()
  }

  const label =
    outcome.source === "deepseek" ? "DeepSeek" : outcome.degraded ? "TinyFish（降级）" : "TinyFish（补查）"
  const good = outcome.hits.filter((h) => typeof h.score === "number" && h.score >= 1.5).length
  const headline = `来源：${label}，共 ${outcome.hits.length} 条${good ? `（优质 ${good} 条）` : ""}`
  lines.push(headline, "")

  const scores = outcome.hits.map((h) => h.score).filter((s): s is number => typeof s === "number")
  if (scores.length > 0 && Math.max(...scores) < LOW_SCORE) {
    lines.push(
      `⚠️ 结果相关度普遍偏低（最高 ${Math.max(...scores).toFixed(2)}），建议更换关键词或增加筛选条件。`,
      "",
    )
  }

  const contentHits = outcome.hits.filter((h) => h.content).length
  if (outcome.needContent && contentHits === 0) {
    lines.push("提示：本次请求了正文，但接口未返回 content（可改用 webfetch 抓取原文）。", "")
  }

  let budget = TOTAL_CONTENT_CHARS
  let omitted = 0

  outcome.hits.forEach((h, i) => {
    const meta: string[] = []
    if (h.site) meta.push(h.site)
    if (h.date) meta.push(formatDate(h.date))
    if (typeof h.authority === "number" && h.authority >= 0) {
      meta.push(h.authority >= 3 ? `权威 ${h.authority}/4（高）` : `权威 ${h.authority}/4`)
    }
    if (typeof h.score === "number") meta.push(`相关 ${h.score.toFixed(2)}${h.score < LOW_SCORE ? "（低）" : ""}`)
    if (typeof h.score === "number" && h.score >= 1.5) meta.push("★优质")

    lines.push(`${i + 1}. ${clip(h.title, TITLE_CHARS) || "(无标题)"}`)
    lines.push(`   ${h.url}`)
    if (meta.length) lines.push(`   ${meta.join(" · ")}`)
    const body = clip(h.summary, SUMMARY_CHARS) || clip(h.snippet, SNIPPET_CHARS)
    if (body) lines.push(`   摘要：${body}`)

    if (h.content) {
      if (budget <= 0) {
        omitted++
        lines.push("   【正文】已省略：本次正文预算已用完")
      } else {
        const allowed = Math.min(PER_HIT_CONTENT_CHARS, budget)
        const taken = takeChars(h.content, allowed)
        budget -= Math.min(taken.total, allowed)
        const title = `   【正文】${taken.total} 字${taken.truncated ? `，已截断至 ${allowed} 字` : ""}`
        lines.push(title)
        for (const row of taken.text.split(/\r?\n/)) lines.push(`   ${row}`)
      }
    }
    lines.push("")
  })

  if (omitted > 0) {
    lines.push(`（另有 ${omitted} 条正文因总预算 ${TOTAL_CONTENT_CHARS} 字已用完而未展示。）`)
  }

  return lines.join("\n").trimEnd()
}

