const WEBSEARCH_INPUT_SCHEMA = {
  type: "object",
  properties: {
    query: {
      type: "string",
      minLength: 1,
      maxLength: QUERY_MAX,
      description:
        "搜索关键词，1–128 字符。支持 site: / -site: / lang: / after: / before: / \"精确短语\" / -排除词 等语法，可组合使用。",
    },
    count: {
      type: "integer",
      minimum: 1,
      maximum: COUNT_MAX,
      description: `返回结果条数，默认 ${COUNT_DEFAULT}，最大 ${COUNT_MAX}。条数不影响计费。`,
    },
    need_content: {
      type: "boolean",
      description:
        "是否返回网页正文（Markdown），用于需要阅读原文细节的场景；会按每条 3000 字、总计 12000 字截断。一般检索保持关闭。",
    },
    ori_question: {
      type: "string",
      maxLength: ORI_QUESTION_MAX,
      description: "触发本次搜索的用户原始问题（可选），有助于理解搜索意图。",
    },
    site: {
      type: "string",
      description: "只搜指定站点，多个用逗号或空格分隔，例如 github.com,huggingface.co。",
    },
    exclude_sites: {
      type: "string",
      description: "排除指定站点，多个用逗号或空格分隔。",
    },
    lang: {
      type: "string",
      description: "限定语言，多个用逗号分隔，例如 zh,en。",
    },
    after: {
      type: "string",
      description: "只返回该日期之后发布的网页，格式 2025、2025-01 或 2025-01-31。",
    },
    before: {
      type: "string",
      description: "只返回该日期之前发布的网页，格式 2025、2025-01 或 2025-01-31。",
    },
    exclude_terms: {
      type: "string",
      description: "排除包含这些词的网页，多个用逗号分隔；含空格视为精确短语。",
    },
  },
  required: ["query"],
  additionalProperties: false,
} as const

export default {
  id: "deepseek-web",
  async setup(ctx: any) {
    await ctx.tool.transform((editor: any) => {
      editor.add({
        name: "websearch",
        description:
          "搜索互联网获取最新信息。优先使用 DeepSeek 自研搜索（中文召回强、带权威度与相关度评分），" +
          "支持条数、正文、原始问题与站点/语言/时间/排除词等筛选；" +
          "当 DeepSeek 不可用（超时、限流、余额不足、鉴权失败）或返回空结果时自动降级到备用搜索，并在结果顶部注明降级原因。",
        input: WEBSEARCH_INPUT_SCHEMA,
        async execute(args: any, context: any) {
          const signal = context?.signal ?? context?.abort
          const outcome = await search(
            {
              query: String(args?.query ?? ""),
              count: typeof args?.count === "number" ? args.count : undefined,
              needContent: args?.need_content === true,
              oriQuestion: typeof args?.ori_question === "string" ? args.ori_question : undefined,
              site: args?.site,
              excludeSites: args?.exclude_sites,
              lang: args?.lang,
              after: args?.after,
              before: args?.before,
              excludeTerms: args?.exclude_terms,
            },
            { signal },
          )
          return {
            content: format(outcome),
            metadata: {
              source: outcome.source,
              hits: outcome.hits.length,
              needContent: outcome.needContent,
              degraded: outcome.degraded,
              errors: outcome.errors,
              query: outcome.query,
            },
          }
        },
      })
    })
  },
}
